<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
use EpaperSaas\Core\{RequestContext,Store,Uuid};use EpaperSaas\Services\{Media,TenantData};
$a=Uuid::v7();$b=Uuid::v7();$pub=Uuid::v7();$slug='isolation-'.substr(str_replace('-','',$pub),0,10);$fail=0;$check=function($ok,$name)use(&$fail){echo($ok?'PASS':'FAIL')." — $name\n";if(!$ok)$fail++;};
try{Store::exec('INSERT INTO ep_tenants(tenant_guid,display_name,status,created_at,updated_at) VALUES(?,"Isolation A","ACTIVE",NOW(6),NOW(6)),(?,"Isolation B","ACTIVE",NOW(6),NOW(6))',[Uuid::toBinary($a),Uuid::toBinary($b)]);RequestContext::set(['tenant_guid'=>$a,'tenant_name'=>'Isolation A','request_guid'=>Uuid::v7(),'correlation_guid'=>Uuid::v7()]);Store::exec('INSERT INTO ep_publications(publication_guid,tenant_guid,publication_code,name,slug,status,created_at,updated_at) VALUES(?,?,"ISO","Isolation Publication",?,"ACTIVE",NOW(6),NOW(6))',[Uuid::toBinary($pub),Uuid::toBinary($a),$slug]);$check((bool)TenantData::publicationBySlug($slug),'Tenant A reads own publication');$tok=Media::token(Uuid::v7(),60);RequestContext::set(['tenant_guid'=>$b,'tenant_name'=>'Isolation B','request_guid'=>Uuid::v7(),'correlation_guid'=>Uuid::v7()]);$check(TenantData::publicationBySlug($slug)===null,'Tenant B cannot read Tenant A publication');try{Media::verify($tok);$cross=false;}catch(Throwable){$cross=true;}$check($cross,'signed media token is tenant-bound');}finally{Store::exec('DELETE FROM ep_publications WHERE tenant_guid IN (?,?)',[Uuid::toBinary($a),Uuid::toBinary($b)]);Store::exec('DELETE FROM ep_tenants WHERE tenant_guid IN (?,?)',[Uuid::toBinary($a),Uuid::toBinary($b)]);}exit($fail?1:0);
